026 IBAN ordinante: IT02D0306936283100000060852 Indirizzo ordinante: VIA GIUSEPPE MAZZINI 8 10 - 30027 SAN DONA DI PIAV ID End to End: NOTPROVIDED"},{"nome_file":"EC 07 2026.csv","data_ok":"2026-07-10","importo":7108.5,"descrizione":"Ordinante: LUCA S.P.A. Causale: ORDINE CONTO Regolazione premio R.C. diversi Polizza 322892076 0835600042830607486181061810IT Data ordine: 10/07/2026 IBAN ordinante: IT79S0835661810000000202710 Indirizzo ordinante: VIA GIOVANNI XXIII 1 - MONASTIER DI TREVISO ID End to End: NOTPROVIDED"}]'::jsonb)
  AS x(nome_file text, data_ok text, importo numeric, descrizione text)
),
upd AS (
  UPDATE movimenti_bancari mb
  SET data_movimento = s.data_ok::date
  FROM src s
  JOIN movimenti_bancari_carichi c ON c.nome_file = s.nome_file
  WHERE mb.carico_id = c.id
    AND round(mb.importo::numeric, 2) = round(s.importo, 2)
    AND mb.descrizione = s.descrizione
    AND mb.data_movimento IS DISTINCT FROM s.data_ok::date
  RETURNING mb.id
)
SELECT count(*)::int AS updated FROM upd;
